  /// A saved config.json: compared with the file as it is, as a diff, and restored.
  function configBackupRow(backup) {
    const detail = el("div", { class: "row-detail hidden" });
    const compare = async () => {
      if (!detail.classList.contains("hidden")) { detail.classList.add("hidden"); return; }
      detail.classList.remove("hidden");
      detail.replaceChildren(el("p", { class: "muted", text: t("Comparing…") }));
      try {
        const [then, now] = await Promise.all([
          api(`/api/config/backups/${encodeURIComponent(backup.name)}`, { raw: true }), api("/api/config", { raw: true })]);
        detail.replaceChildren(diffView(jsonDiff(JSON.parse(then), JSON.parse(now)), t("this backup"), t("config.json now")));
      } catch (e) { detail.replaceChildren(el("p", { class: "error", text: e.message })); }
    };
    const restore = async () => {
      if (!(await confirmAction({ title: t("Restore this config.json?"), confirmLabel: t("Restore"), text: t("It replaces config.json (which is kept as a backup first) and applies at once, as a save does: plugins reload, and the bridge block restarts homeswift.") }))) return;
      await busy(null, async () => {
        const result = await api(`/api/config/backups/${encodeURIComponent(backup.name)}/restore`, { method: "POST" });
        detail.classList.remove("hidden");
        detail.replaceChildren(el("p", { class: "ok", text: `${result.changes.length ? t("Changed: {changes}.", { changes: result.changes.join(", ") }) : t("Nothing changed.")} ${app().savedText(result)}` }));
      });
    };
    return el("div", { class: "row-block" },
      el("div", { class: "row" },
        el("div", { class: "who" }, el("strong", { text: backup.date ? fullDate.format(new Date(backup.date)) : backup.name }), el("div", { class: "muted mono", text: backup.name })),
        el("button", { actionIcon: "code", class: "link", text: t("Compare"), onclick: compare }),
        menuButton(t("Actions for {name}", { name: backup.name }), () => [
          { label: t("Compare with config.json"), icon: "code", onSelect: compare },
          { label: t("Restore…"), icon: "restore", danger: true, onSelect: restore },
        ])),
      detail);
  }

  /// A diff of `jsonDiff` lines: the changes with three lines around them, the rest folded.
  function diffView(lines, before, after) {
    if (!lines.some((line) => line.kind !== "same")) return el("p", { class: "muted", text: t("The same as config.json now.") });
    const keep = new Set();
    lines.forEach((line, index) => { if (line.kind !== "same") for (let k = index - 3; k <= index + 3; k++) keep.add(k); });
    const nodes = [];
    let folded = 0;
    lines.forEach((line, index) => {
      if (!keep.has(index)) { folded++; return; }
      if (folded) { nodes.push(el("span", { class: "diff-fold", text: `  … ${tn("{n} unchanged line", "{n} unchanged lines", folded)}\n` })); folded = 0; }
      nodes.push(el("span", { class: `diff-${line.kind}`, text: `${line.kind === "add" ? "+ " : line.kind === "remove" ? "- " : "  "}${line.text}\n` }));
    });
    if (folded) nodes.push(el("span", { class: "diff-fold", text: `  … ${tn("{n} unchanged line", "{n} unchanged lines", folded)}\n` }));
    return el("div", {}, el("p", { class: "muted", text: `− ${before}   + ${after}` }), el("pre", { class: "diff" }, nodes));
  }

  // ---- Audit log -----------------------------------------------------------------------------------------

  const outcomes = [["", t("Every outcome")], ["ok", t("Done [outcome]")], ["failed", t("Failed")], ["notConfirmed", t("Not confirmed")]];
  const spans = [["24h", t("Last 24 hours")], ["7d", t("Last 7 days")], ["30d", t("Last 30 days")], ["", t("Everything kept")]];

  async function auditPage(main) {
    const params = new URLSearchParams(location.search);
    const tool = el("input", { type: "search", class: "search", placeholder: t("Tool or route"), value: params.get("tool") ?? "", "aria-label": t("Filter by tool") });
    const client = el("input", { type: "search", class: "search", placeholder: t("Client or user"), value: params.get("client") ?? "", "aria-label": t("Filter by client") });
    const select = (choices, value, label) => {
      const control = el("button", { class: "audit-picker", type: "button", "aria-label": label, "aria-haspopup": "menu" });
      control.value = value;
      control.counts = new Map();
      const counted = (v, label) => control.counts.has(v) ? `${label} (${control.counts.get(v)})` : label;
      const paint = () => control.replaceChildren(el("span", { text: counted(control.value, choices.find(([v]) => v === control.value)?.[1] ?? label) }), el("span", { text: "⌄", "aria-hidden": "true" }));
      control.addEventListener("click", () => HomeswiftCommon.menu(control, choices.map(([v, text]) => ({ label: text, count: control.counts.get(v), disabledReason: t("No audit entries match the current filters."), checked: control.value === v, onSelect: () => { control.value = v; paint(); control.dispatchEvent(new Event("change")); } }))));
      control.paint = paint;
      control.addEventListener("change", paint);
      paint();
      return control;
    };
    const outcome = select(outcomes, params.get("outcome") ?? "", t("Outcome"));
    const since = select(spans, params.has("since") ? params.get("since") : "7d", t("Time range"));
    const count = el("span", { class: "muted count", role: "status", "aria-live": "polite" });
    const body = el("div", {});
    let loads = 0;   // the answer drawn is the last request's, however they arrive
    async function load() {
      const own = ++loads;
      const query = new URLSearchParams();
      if (tool.value.trim()) query.set("tool", tool.value.trim());
      if (client.value.trim()) query.set("client", client.value.trim());
      if (outcome.value) query.set("outcome", outcome.value);
      query.set("since", since.value);
      window.history.replaceState(null, "", `/settings/audit?${query}`);
      if (!since.value) query.delete("since");
      count.textContent = t("Loading…");
      for (const control of [outcome, since]) { control.counts.clear(); control.paint(); }
      // The server counts each alternative against the current text and the other selected filter, in the same pass.
      query.set("spans", spans.map(([value]) => value).join(","));
      let found;
      try { found = await api(`/api/audit?${query}`); } catch (e) { if (own === loads) count.textContent = e.message; return; }
      if (own !== loads) return;
      for (const [control, key] of [[outcome, "outcome"], [since, "since"]]) {
        control.counts = new Map(Object.entries(found.counts?.[key] ?? {}));
        control.paint();
      }
      if (!found.enabled) {
        count.textContent = "";
        body.replaceChildren(el("div", { class: "card empty" }, el("p", { class: "muted", text: t("The audit log is off: the HomeswiftAiKit block's mcp.http says auditLog: false.") })));
        return;
      }
      count.textContent = t("{shown} of {total}", { shown: found.entries.length, total: found.total });
      body.replaceChildren(found.entries.length ? el("div", { class: "card audit-results" }, el("div", { class: "table-scroll" }, el("table", { class: "data-table" },
        el("thead", {}, el("tr", {}, [t("Time"), t("Who"), t("What"), t("Outcome"), t("Details")].map((text) => el("th", { text })))),
        el("tbody", {}, found.entries.map(auditRow)))), el("p", { class: "muted note", text: found.path }))
        : el("div", { class: "card empty" }, el("span", { class: "empty-glyph" }, HomeswiftCommon.icon("shield")), el("p", { class: "muted", text: t("Nothing in this range matches.") })));
    }
    let typing = null;
    for (const input of [tool, client]) input.addEventListener("input", () => { clearTimeout(typing); typing = setTimeout(load, 250); });
    for (const choice of [outcome, since]) choice.addEventListener("change", () => { clearTimeout(typing); typing = setTimeout(load, 0); });
    app().show(main,
      app().pageHead(t("Audit log"), t("Every change made through the MCP server, the Assistant's chat and this web UI, with who made it.")),
      subnav("audit"),
      el("div", { class: "card audit-filters" },
        el("div", { class: "audit-filter-grid" },
          el("label", {}, el("span", { text: t("Time range") }), since),
          el("label", {}, el("span", { text: t("Outcome") }), outcome),
          el("label", {}, el("span", { text: t("Tool or route") }), tool),
          el("label", {}, el("span", { text: t("Client or user") }), client)),
        el("div", { class: "audit-filter-footer" }, count,
          HomeswiftCommon.clearFilters([[tool, ""], [client, ""], [outcome, ""], [since, "7d"]], { reset: () => clearTimeout(typing) }))),
      body);
    await load();
  }

  function auditRow(entry) {
    const [text, kind] = entry.notConfirmed ? [t("Not confirmed"), "away"] : entry.ok ? [t("Done [outcome]"), "on"] : [t("Failed"), "away"];
    const args = entry.args && Object.keys(entry.args).length ? JSON.stringify(entry.args) : "";
    return el("tr", {},
      el("td", { text: entry.ts ? dateTime.format(new Date(entry.ts)) : "–", title: entry.ts ?? "" }),
      el("td", {}, el("strong", { text: entry.principal ?? "?" }), el("div", { class: "muted", text: `${entry.client ?? "?"} · ${entry.scope ?? ""}` })),
      el("td", { class: "mono", text: entry.dryRun ? t("{tool} (dry run)", { tool: entry.tool }) : entry.tool }),
      el("td", {}, el("span", { class: `pill status ${kind}`, text })),
      el("td", { class: "audit-details" }, entry.error ? el("div", { class: "error", text: entry.error }) : null, args ? el("details", {}, el("summary", { text: t("Details") }), HomeswiftCommon.jsonView(entry.args)) : null));
  }

  // ---- An accessory's history -----------------------------------------------------------------------------

  const historyUnits = { celsius: "°C", percentage: "%", W: "W", lux: "lx", hPa: "hPa", ppm: "ppm", "µg/m³": "µg/m³" };
  const historyLabels = {
    CurrentTemperature: t("Temperature"), TargetTemperature: t("Target temperature"), CurrentRelativeHumidity: t("Humidity"), AirPressure: t("Air pressure"),
    AirQuality: t("Air quality"), VOCDensity: t("VOC density"), CurrentConsumption: t("Power [watts]"), CurrentAmbientLightLevel: t("Light level"), On: t("On"),
    ContactSensorState: t("Contact"), MotionDetected: t("Motion"), ValvePosition: t("Valve position"), WaterAmount: t("Water"),
  };

  /// A sheet with the accessory's recorded values (its Eve history) as charts, over a day, a week or four weeks.
  function showHistory(accessory) {
    const ranges = [[24, t("24 hours")], [168, t("7 days")], [672, t("4 weeks")]];
    let hours = 24;
    const charts = el("div", { class: "chart-grid" });
    const note = el("p", { class: "muted" });
    const group = el("div", { class: "group", role: "group", "aria-label": t("Time range") }, ranges.map(([value, text]) =>
      el("button", { type: "button", text, class: value === hours ? "on" : "", "aria-pressed": String(value === hours), onclick: (event) => {
        hours = value;
        for (const button of group.children) { button.classList.toggle("on", button === event.currentTarget); button.setAttribute("aria-pressed", String(button === event.currentTarget)); }
        load();
      } })));
    const close = el("button", { actionIcon: "check", type: "button", text: t("Done"), class: "primary" });
    const dialog = el("dialog", { class: "admin-dialog card wide", "aria-labelledby": "history-title" },
      el("div", { class: "page-head" }, el("div", { class: "who" }, el("h2", { id: "history-title", text: accessory.name }), el("p", { class: "muted", text: t("Recorded values, as Eve shows them") })),
        el("div", { class: "tools" }, group, HomeswiftCommon.clearFilters([], { active: () => hours !== 24, events: [[group, "click"]], reset: () => group.firstElementChild.click() }))),
      charts, note, el("div", { class: "actions" }, close));
    close.addEventListener("click", () => dialog.close());
    dialog.addEventListener("close", () => dialog.remove());
    document.body.append(dialog);
    dialog.showModal();

    async function load() {
      // Ranges chosen quickly one after the other: only the last one's answer is drawn.
      const asked = hours;
      charts.classList.add("loading");
      let found;
      try { found = await api(`/api/accessories/${encodeURIComponent(accessory.id)}/history?hours=${hours}&points=240`); }
      catch (e) { if (asked === hours) { charts.classList.remove("loading"); note.className = "error"; note.textContent = e.message; } return; }
      if (asked !== hours) return;
      charts.classList.remove("loading");
      note.className = "muted";
      note.textContent = found.note != null ? HomeswiftI18n.message(found.note) : t("Ten-minute averages, kept four weeks; each point here averages those in its span.");
      const from = new Date(found.from).getTime(), to = new Date(found.to).getTime();
      charts.replaceChildren(...found.series.map((series) => {
        const unit = historyUnits[series.unit] ?? series.unit ?? "";
        const format = (value) => `${Math.abs(value) < 10 && value % 1 ? value.toFixed(1) : Math.round(value * 10) / 10}${unit ? ` ${unit}` : ""}`;
        const points = series.points.map(([time, value]) => ({ time: new Date(time).getTime(), value }));
        const gaps = points.slice(1).map((point, index) => point.time - points[index].time).sort((a, b) => a - b);
        const step = Math.max(gaps[Math.floor(gaps.length / 2)] ?? 600000, 600000);
        const body = el("div", { class: "chart-body" });
        const card = el("div", { class: "card chart-card" },
          el("div", { class: "chart-head" }, el("div", { class: "who" }, el("strong", { text: historyLabels[series.type] ?? series.type }),
            el("div", { class: "muted", text: t("Lowest {min} · highest {max} · average {average}", { min: format(series.min.value), max: format(series.max.value), average: format(series.avg) }) })),
          el("b", { class: "chart-figure", text: format(series.last.value), title: t("Last, {date}", { date: when(series.last.at) }) })),
          body);
        HomeswiftChart.lineChart(body, { title: historyLabels[series.type] ?? series.type, series: [{ label: historyLabels[series.type] ?? series.type, tone: 1, value: (point) => point.value }],
          format, points, from, to, step });
        return card;
      }));
    }
    load();
  }

  window.HomeswiftAdmin = { view, history: showHistory, confirmAction };
})();

"""#),
        "app.js": WebFile(contentType: "text/javascript; charset=utf-8", body: #"""
// Homeswift web UI: one page, plain JavaScript, no dependencies. Talks to /api/* with the session cookie.
(() => {
  "use strict";

  const { $, el, tile, sparkle, menuButton, copyText, markdown, jsonEditor, jsonView, fact, setPaused, slug, withSlugs } = HomeswiftCommon;
  const { t, tn } = HomeswiftI18n;

  const show = (main, ...nodes) => main.replaceChildren(...nodes.flat().filter(Boolean));
  /// A translated sentence with elements in it: each `{name}` of `text` is the node `nodes[name]`.
  const withNodes = (text, nodes) => text.split(/(\{\w+\})/).filter(Boolean).map((part) => (/^\{\w+\}$/.test(part) && nodes[part.slice(1, -1)]) || part);

  /// `problems`: what a save changed that its plugin's schema refuses, each with its path (`ConfigSchemaError`).
  class ApiError extends Error { constructor(status, message, problems) { super(message); this.status = status; this.problems = problems; } }

  async function api(path, { method = "GET", body, raw = false } = {}) {
    // The Assistant answers in the page's language.
    const options = { method, credentials: "same-origin", headers: { "Accept-Language": HomeswiftI18n.locale } };
    if (body !== undefined) { options.headers["Content-Type"] = "application/json"; options.body = typeof body === "string" ? body : JSON.stringify(body); }
    const response = await fetch(path, options);
    if (response.status === 401 && !path.startsWith("/api/auth/")) { showAuth(); throw new ApiError(401, "signed out"); }
    const text = await response.text();
    if (!response.ok) {
      let message = text, problems;
      try { ({ error: message = text, problems } = JSON.parse(text)); } catch {}
      throw new ApiError(response.status, HomeswiftI18n.message(message || `HTTP ${response.status}`), problems);
    }
    return raw ? text : (text ? JSON.parse(text) : null);
  }

  // ---- Authentication ------------------------------------------------------

  let auth = null;
  // The server's secret-key rule (see the settings page): set with the plugin list, read by the JSON secret note.
  let secretRule = null;

  async function loadAuth() {
    auth = await api("/api/auth/state");
    if (auth.authenticated) showApp(); else showAuth();
  }

  function showAuth() {
    $("#app").classList.add("hidden");
    $("#auth").classList.remove("hidden");
    closeEvents();
    // The chat lives outside #app: closed and emptied, so the next person at this browser does not see it.
    window.HomeswiftChat?.signedOut();
    const setup = auth && auth.setupNeeded;
    $("#auth-text").textContent = setup
      ? t("Create the administrator account for this bridge. The set-up code is in the bridge's output, next to the web UI address.")
      : t("Sign in to manage the bridge.");
    $("#auth-submit").textContent = setup ? t("Create account") : t("Sign in");
    $("input[name=password]", $("#auth-form")).autocomplete = setup ? "new-password" : "current-password";
    $("#auth-setup-code").classList.toggle("hidden", !setup);
    $("input[name=setupCode]", $("#auth-form")).required = !!setup;
    askCode(false);
    const form = $("#auth-form");
    if (setup && !setupGauge) {
      setupGauge = strengthGauge(form.password, () => form.username.value);
      form.password.closest("label").after(setupGauge);
      form.username.addEventListener("input", () => setupGauge.refresh());
    }
    setupGauge?.classList.toggle("hidden", !setup);
  }
  let setupGauge = null;

  /// The login's second step: with two-factor authentication on, the bridge asks for the authenticator app's code.
  function askCode(asked) {
    const form = $("#auth-form");
    $("#auth-otp").classList.toggle("hidden", !asked);
    form.otp.required = asked;
    if (!asked) form.otp.value = "";
    else form.otp.focus();
  }
  // Another username or password starts over: the code is only asked once those are right.
  for (const name of ["username", "password"]) $("#auth-form")[name].addEventListener("input", () => askCode(false));

  $("#auth-form").addEventListener("submit", async (event) => {
    event.preventDefault();
    const form = event.target;
    const error = $("#auth-error");
    error.textContent = "";
    // Feedback on the press: the button says what happens while the bridge checks the password.
    const submit = $("#auth-submit");
    const label = submit.textContent;
    submit.disabled = true;
    submit.classList.add("busy");
    submit.textContent = auth && auth.setupNeeded ? t("Creating the account…") : t("Signing in…");
    const body = { username: form.username.value, password: form.password.value };
    try {
      if (auth && auth.setupNeeded) {
        if (setupGauge && !(await setupGauge.acceptable())) throw new Error(t("The password is not strong enough yet: the gauge says what is missing."));
        body.setupCode = form.setupCode.value;
      }
      if (!$("#auth-otp").classList.contains("hidden")) body.otp = form.otp.value;
      const firstRun = Boolean(auth && auth.setupNeeded);
      await api(auth && auth.setupNeeded ? "/api/auth/setup" : "/api/auth/login", { method: "POST", body });
      form.password.value = "";
      askCode(false);
      await loadAuth();
      // The first account: with no plugin yet, the welcome page offers the import (import.js).
      if (firstRun) window.HomeswiftImport?.afterSetup();
    } catch (e) {
      if (e.status === 412) { askCode(true); return; }
      error.textContent = e.message;
      if (body.otp !== undefined) { form.otp.value = ""; form.otp.focus(); }
    } finally {
      submit.disabled = false;
      submit.classList.remove("busy");
      submit.textContent = label;
    }
  });

  const signOut = async () => { try { await api("/api/auth/logout", { method: "POST" }); } catch {} await loadAuth(); };

  /// The name the header shows: the user's display name, else their username; none without sign-in.
  const shownName = () => (auth.mode === "form" ? (auth.name && auth.name !== auth.username ? auth.name : auth.username || "") : "");

  /// The header's account button: the user's initial on the accent (a person without sign-in), the name beside it on
  /// a wide window.
  function drawUser() {
    const name = shownName();
    $("#user .user-avatar").replaceChildren(auth.mode === "form" && name ? name.slice(0, 1).toUpperCase() : HomeswiftCommon.icon("user"));
    $("#user .user-name").textContent = name;
  }

  // Its menu: who is signed in and as what, their account and appearance, the users for an administrator, signing out.
  $("#user").addEventListener("click", (event) => {
    event.stopPropagation();
    openUserMenu(event.currentTarget, event.detail === 0);
  });
  document.addEventListener("homeswift-account-menu", (event) => openUserMenu(event.detail.trigger, event.detail.keyboard));
  function openUserMenu(trigger, keyboard = false) {
    const form = auth.mode === "form";
    HomeswiftCommon.menu(trigger, [
      form ? { heading: shownName(), detail: isAdmin() ? t("{username} · Administrator", { username: auth.username }) : auth.username } : { heading: t("No sign-in"), detail: t("Anyone who opens this web UI uses it") },
      { label: form ? t("Your account") : t("Account"), icon: "user", href: "/account" },
      { label: t("Appearance"), icon: "sliders", href: "/appearance" },
      form && isAdmin() ? { label: t("Users and tokens"), icon: "users", href: "/users" } : null,
      // A phone's tab bar has no room for Settings: it is here, as the header holds it on a wider window.
      isAdmin() && matchMedia("(max-width: 640px)").matches ? { label: t("Settings"), icon: "gear", href: "/settings" } : null,
      { label: t("Language"), icon: flag(HomeswiftI18n.language), onSelect: () => setTimeout(() => languageMenu(trigger)) },
      form ? { separator: true } : null,
      form ? { label: t("Sign out"), icon: "logout", onSelect: signOut } : null,
    ], { keyboard });
  }

  const flag = (code) => el("span", { class: "menu-flag", "aria-hidden": "true", text: code ? HomeswiftI18n.flags[code] : "🌐" });

  /// The language, from the account menu: Automatic (the browser's) or one of the four, each in its own name. Saved
  /// with the user's preferences, which opens the page again in it.
  function languageMenu(trigger = $("#user")) {
    const current = HomeswiftCommon.preferences().language || "auto";
    const choose = async (code) => {
      if (code === current) return;
      try { HomeswiftCommon.applyPreferences(await api("/api/preferences", { method: "PUT", body: { language: code } })); } catch (e) { alert(e.message); }
    };
    HomeswiftCommon.menu(trigger, [
      { label: t("Automatic"), icon: flag(null), checked: current === "auto", onSelect: () => choose("auto") },
      ...HomeswiftI18n.languages.map((code) => ({ label: HomeswiftI18n.names[code], icon: flag(code), checked: current === code, onSelect: () => choose(code) })),
    ]);
  }

  // The sign-in page's flags: the language before anyone signs in.
  $("#auth-form").append(el("div", { class: "auth-languages", role: "group", "aria-label": t("Language") },
    HomeswiftI18n.languages.map((code) => el("button", { type: "button", text: HomeswiftI18n.flags[code], title: HomeswiftI18n.names[code], "aria-label": HomeswiftI18n.names[code],
      "aria-pressed": String(code === HomeswiftI18n.language), onclick: () => HomeswiftI18n.choose(code) }))));

  /// What a save did: applied at once, homeswift restarting by itself (the bridge block), or, when it
  /// cannot, what still waits for a restart (which also shows the banner).
  function savedText(result) {
    if (result.restarting) { waitForRestart(); return t("Saved. Homeswift restarts by itself to apply the bridge settings…"); }
    const pending = result.restartNeeded || [];
    $("#banner").classList.toggle("hidden", pending.length === 0);
    return pending.length ? t("Saved. Restart homeswift to apply the rest: {pending}.", { pending: pending.map((item) => HomeswiftI18n.message(item)).join("; ") }) : t("Saved and applied.");
  }

  // ---- Restart -------------------------------------------------------------

  function confirmRestart() {
    return new Promise((resolve) => {
      const dialog = el("dialog", { class: "restart-overlay restart-confirm", "aria-labelledby": "restart-confirm-title", "aria-describedby": "restart-confirm-description" });
      const finish = (accepted) => { dialog.close(); dialog.remove(); resolve(accepted); };
      const cancel = el("button", { actionIcon: "close", text: t("Cancel"), onclick: () => finish(false) });
      dialog.append(
        el("div", { class: "restart-confirm-icon", "aria-hidden": "true" }, HomeswiftCommon.icon("power")),
        el("h2", { id: "restart-confirm-title", text: t("Restart Homeswift?") }),
        el("p", { id: "restart-confirm-description", text: t("Your accessories will disconnect briefly. This page will reconnect automatically when Homeswift is ready.") }),
        el("div", { class: "restart-confirm-actions" }, cancel,
          el("button", { actionIcon: "power", class: "primary", text: t("Restart"), onclick: () => finish(true) })));
      dialog.addEventListener("cancel", (event) => { event.preventDefault(); finish(false); });
      document.body.append(dialog); dialog.showModal(); cancel.focus();
    });
  }

  async function restartBridge(event) {
    const button = event.currentTarget;
    if (!await confirmRestart()) return;
    button.disabled = true;
    showRestartOverlay();
    const started = Date.now();
    try {
      const response = await fetch("/api/restart", { method: "POST", credentials: "same-origin", signal: AbortSignal.timeout(4000) });
      if (!response.ok) throw new ApiError(response.status, `HTTP ${response.status}`);
      // The process may exit before completing the response body. Headers are enough.
    } catch (e) {
      if (e instanceof ApiError) {
        closeRestartOverlay();
        alert(e.message); button.disabled = false; return;
      }
      // A disconnected or aborted request can mean the restart already began.
    }
    waitForRestart(started);
  }

  let restartOverlay = null;
  let restartPolling = false;
  function showRestartOverlay() {
    if (restartOverlay?.isConnected) return restartOverlay;
    restartOverlay = el("dialog", { class: "restart-overlay", "aria-labelledby": "restart-heading", "aria-describedby": "restart-message" },
      el("span", { class: "spinner", "aria-hidden": "true" }),
      el("h2", { id: "restart-heading", text: t("Restarting homeswift…") }),
      el("p", { id: "restart-message", role: "status", "aria-live": "polite", text: t("Please wait. This page will reconnect automatically.") }));
    restartOverlay.addEventListener("cancel", (event) => event.preventDefault());
    document.body.append(restartOverlay); restartOverlay.showModal();
    return restartOverlay;
  }

  function closeRestartOverlay() {
    restartOverlay?.close();
    restartOverlay?.remove();
    restartOverlay = null;
  }

  async function finishRestart() {
    if (restartOverlay?.isConnected && !matchMedia("(prefers-reduced-motion: reduce)").matches) {
      restartOverlay.classList.add("restart-leaving");
      await new Promise((resolve) => setTimeout(resolve, 220));
    }
    closeRestartOverlay();
    restartPolling = false;
    const restartButton = $("#restart");
    if (restartButton) restartButton.disabled = false;
    // Keep the current DOM, scroll position, filters and unsaved edits intact.
    try {
      auth = await api("/api/auth/state");
      if (!auth.authenticated) { showAuth(); return; }
      showSections();
      openEvents();
      $("#banner").classList.add("hidden");
      document.querySelectorAll(".dashboard-quick-actions button").forEach((button) => { button.disabled = false; });
    } catch (error) { console.error("Could not reconnect after restart", error); }
  }

  /// A modal blocks controls until a younger process answers, with recovery if the restart times out.
  function waitForRestart(started = Date.now()) {
    if (restartPolling) return;
    restartPolling = true;
    closeEvents();
    const deadline = Date.now() + 90000;
    const overlay = showRestartOverlay();
    let wasOffline = false;
    let healthyReplies = 0;
    const poll = async () => {
      try {
        const response = await fetch("/api/status", { credentials: "same-origin", cache: "no-store", signal: AbortSignal.timeout(5000) });
        if (response.ok) {
          const status = await response.json();
          healthyReplies++;
          const younger = Number.isFinite(status.uptimeSeconds) && status.uptimeSeconds < (Date.now() - started) / 1000 + 5;
          if (younger || (wasOffline && healthyReplies >= 2)) { await finishRestart(); return; }
        } else if (response.status === 401) { await finishRestart(); return; }
      } catch { wasOffline = true; healthyReplies = 0; }
      if (Date.now() < deadline) setTimeout(poll, 1000);
      else {
        restartPolling = false;
        overlay.querySelector(".spinner")?.remove();
        overlay.querySelector("#restart-heading").textContent = t("homeswift did not come back; check its log.");
        overlay.querySelector("#restart-message").textContent = "";
        overlay.append(el("button", { actionIcon: "restore", class: "primary", text: t("Try again"), onclick: () => {
          closeRestartOverlay();
          waitForRestart(started);
        } }));
      }
    };
    setTimeout(poll, 1500);
  }
  $("#restart").addEventListener("click", restartBridge);

  function showApp() {
    $("#auth").classList.add("hidden");
    $("#app").classList.remove("hidden");
    drawUser();
    HomeswiftCommon.tabBar({ parent: $("#app") });
    showSections();
    HomeswiftChat.mount();
    openEvents();
    // The user's theme, wallpaper and units; a page showing temperatures draws again when the unit changed.
    const shownUnit = HomeswiftCommon.preferences().temperatureUnit;
    HomeswiftCommon.loadPreferences().then((preferences) => {
      if (preferences.temperatureUnit !== shownUnit && ["/", "/status", "/accessories"].includes(location.pathname)) route();
    });
    route();
  }

  // ---- Roles -----------------------------------------------------------------
  // As Glass UI's: a user who is not an administrator sees Status and Accessories (and controls accessories); the
  // plugins, config.json, the log and the users are an administrator's. The server refuses the rest anyway.

  const adminSections = new Set(["plugins", "config", "logs", "settings", "users", "import", "welcome"]);
  const isAdmin = () => Boolean(auth && auth.admin);

  /// Shows the header's and the tab bar's sections the user may open.
  function showSections() {
    for (const link of document.querySelectorAll("nav a")) {
      const section = (link.getAttribute("href") || "").split("/")[1];
      const users = section === "users";
      link.classList.toggle("hidden", adminSections.has(section) && (!isAdmin() || (users && auth.mode !== "form")));
    }
    drawUser();
  }

  // ---- Routing -------------------------------------------------------------

  // A path is a view and its arguments: /status (or /), /accessories, /plugins, /plugins/<slug>/expert[/json]
  // (a block's settings; /plugins/<slug> itself is the plugin's own page when it has one), /plugins/add/<platform>,
  // /config, /logs[/<accessory>]?since=…&level=…&q=…, /account. Pages below a section keep it lit in the header.
  const views = {};
  let leaveGuard = null;   // a page with unsaved changes: false keeps it
  let shownPath = null;
  function route() {
    const decode = (part) => { try { return decodeURIComponent(part); } catch { return part; } };
    let [name = "status", ...args] = location.pathname.split("/").filter(Boolean).map(decode);
    if (adminSections.has(name) && !isAdmin()) {
      // An administrator's view, from a link or a bookmark: Status instead.
      history.replaceState(null, "", "/status");
      [name, args] = ["status", []];
    }
    for (const link of document.querySelectorAll("nav a")) {
      const current = link.getAttribute("href") === `/${name}`;
