  let info = null;      // what /api/assistant answered
  let panel = null;     // the parts, once built
  const openness = { value: 0, velocity: 0, frame: 0 };
  let items = [];
  let nodes = [];
  let running = false;
  let usage = null;
  let spoken = false;   // the running turn started from the mic: read its answer out
