        hero.replaceChildren(...(value ? [value] : []));
        if (shade) {
          const { min, max } = built.slide ?? { min: 0, max: 100 };
          shade.style.setProperty("--closed", `${sliding !== null ? 100 - (sliding - min) / (max - min) * 100 : built.shade()}%`);
        }
